90	/// Minimal, strict DER decoder and the slice of X.509 needed by `inspect`.
91	mod x509 {
92	    use std::fmt::Write;
93	
94	    pub(super) struct Cert {
95	        pub(super) subject: String,
96	        pub(super) issuer: String,
97	        pub(super) serial_hex: String,
98	        pub(super) not_before: String,
99	        pub(super) not_after: String,
100	    }
101	
102	    #[derive(Clone, Copy)]
103	    struct Tlv<'a> {
104	        tag: u8,
105	        content: &'a [u8],
106	    }
107	
108	    const TAG_INTEGER: u8 = 0x02;
109	    const TAG_BIT_STRING: u8 = 0x03;
110	    const TAG_OID: u8 = 0x06;
111	    const TAG_SEQUENCE: u8 = 0x30;
112	    const TAG_SET: u8 = 0x31;
113	    const TAG_UTC_TIME: u8 = 0x17;
114	    const TAG_GENERALIZED_TIME: u8 = 0x18;
115	
116	    /// Read exactly one DER TLV. Rejects indefinite length, non-minimal
117	    /// length encodings and truncated data.
118	    fn read_tlv(buf: &[u8]) -> Result<(Tlv<'_>, &[u8]), String> {
119	        let tag = *buf.first().ok_or_else(|| "unexpected end of data".to_string())?;
120	        if tag & 0x1F == 0x1F {
121	            return Err("multi-byte tags are not supported".to_string());
122	        }
123	        let first_len = *buf.get(1).ok_or_else(|| "truncated length".to_string())?;
124	        let (len, header_len) = match first_len {
125	            0x00..=0x7F => (first_len as usize, 2),
126	            0x80 => return Err("indefinite length is not valid DER".to_string()),
127	            0xFF => return Err("reserved length byte".to_string()),
128	            long => {
129	                let n = (long & 0x7F) as usize;
130	                if !(1..=4).contains(&n) {
131	                    return Err("length is too large".to_string());
132	                }
133	                let bytes = buf
134	                    .get(2..2 + n)
135	                    .ok_or_else(|| "truncated long length".to_string())?;
136	                if bytes[0] == 0 {
137	                    return Err("non-minimal length encoding".to_string());
138	                }
139	                let mut len = 0usize;
140	                for &b in bytes {
141	                    len = len
142	                        .checked_shl(8)
143	                        .and_then(|l| l.checked_add(b as usize))
144	                        .ok_or_else(|| "length overflow".to_string())?;
145	                }
146	                if len < 0x80 {
147	                    return Err("non-minimal length encoding".to_string());
148	                }
149	                (len, 2 + n)
150	            }
151	        };
152	        let total = header_len
153	            .checked_add(len)
154	            .filter(|&t| t <= buf.len())
155	            .ok_or_else(|| "truncated TLV content".to_string())?;
156	        Ok((
157	            Tlv {
158	                tag,
159	                content: &buf[header_len..total],
160	            },
161	            &buf[total..],
162	        ))
163	    }
164	
165	    fn read_tagged<'a>(buf: &'a [u8], tag: u8, what: &str) -> Result<(Tlv<'a>, &'a [u8]), String> {
166	        let (tlv, rest) = read_tlv(buf)?;
167	        if tlv.tag != tag {
168	            return Err(format!("expected {what} (tag 0x{tag:02X}), got 0x{:02X}", tlv.tag));
169	        }
170	        Ok((tlv, rest))
171	    }
172	
173	    pub(super) fn parse(bytes: &[u8]) -> Result<Cert, String> {
174	        // Certificate ::= SEQUENCE { tbsCertificate, signatureAlgorithm,
175	        // signatureValue BIT STRING } — and nothing trailing.
176	        let (cert, rest) = read_tagged(bytes, TAG_SEQUENCE, "Certificate SEQUENCE")?;
177	        if !rest.is_empty() {
178	            return Err(format!("{} trailing byte(s) after certificate", rest.len()));
179	        }
180	
181	        let c = cert.content;
182	        let (tbs, c) = read_tagged(c, TAG_SEQUENCE, "tbsCertificate")?;
183	        let (_sig_alg, c) = read_tagged(c, TAG_SEQUENCE, "signatureAlgorithm")?;
184	        let (sig_value, c) = read_tlv(c)?;
185	        if sig_value.tag != TAG_BIT_STRING {
186	            return Err("signature must be a BIT STRING".to_string());
187	        }
188	        if sig_value.content.is_empty() || sig_value.content[0] > 7 {
189	            return Err("invalid signature BIT STRING".to_string());
190	        }
191	        if !c.is_empty() {
192	            return Err("trailing data in Certificate".to_string());
193	        }
194	
195	        // TBSCertificate ::= SEQUENCE {
196	        //   version [0] EXPLICIT Version DEFAULT v1, serialNumber, signature,
197	        //   issuer, validity, subject, subjectPublicKeyInfo, ... }
198	        let t = tbs.content;
199	        let (first, t2) = read_tlv(t)?;
200	        let t = if first.tag == 0xA0 {
201	            let (version, vrest) = read_tagged(first.content, TAG_INTEGER, "version")?;
202	            if !vrest.is_empty() || version.content.len() != 1 || version.content[0] > 2 {
203	                return Err("invalid certificate version".to_string());
204	            }
205	            t2
206	        } else {
207	            t // No explicit version: v1 certificate.
208	        };
209	
210	        let (serial, t3) = read_tagged(t, TAG_INTEGER, "serialNumber")?;
211	        let t = t3;
212	        let (_tbs_sig, t) = read_tagged(t, TAG_SEQUENCE, "tbs signatureAlgorithm")?;
213	        let (issuer, t) = read_tagged(t, TAG_SEQUENCE, "issuer")?;
214	        let (validity, t) = read_tagged(t, TAG_SEQUENCE, "validity")?;
215	        let (subject, t) = read_tagged(t, TAG_SEQUENCE, "subject")?;
216	        let (_spki, mut t) = read_tagged(t, TAG_SEQUENCE, "subjectPublicKeyInfo")?;
217	        // Remaining fields (issuerUniqueID, subjectUniqueID, extensions, ...)
218	        // are optional; they must still each be well-formed TLVs.
219	        while !t.is_empty() {
220	            let (_, rest) = read_tlv(t)?;
221	            t = rest;
222	        }
223	
224	        let serial_hex = format_serial(serial.content)?;
225	        let issuer = format_name(issuer)?;
226	        let subject = format_name(subject)?;
227	
228	        let v = validity.content;
229	        let (nb, v2) = read_tlv(v)?;
230	        let (na, v3) = read_tlv(v2)?;
231	        if !v3.is_empty() {
232	            return Err("trailing data in validity".to_string());
233	        }
234	        let not_before = format_time(nb)?;
235	        let not_after = format_time(na)?;
236	
237	        Ok(Cert {
238	            subject,
239	            issuer,
240	            serial_hex,
241	            not_before,
242	            not_after,
243	        })
244	    }
245	
246	    /// Render the serial number as upper-case hex, matching the integer value
247	    /// (a DER sign-padding 0x00 byte is not part of the number).
248	    fn format_serial(content: &[u8]) -> Result<String, String> {
249	        if content.is_empty() {
250	            return Err("empty serial number".to_string());
251	        }
252	        if content.len() > 1 && content[0] == 0xFF && content[1] & 0x80 == 0 {
253	            return Err("non-minimal serial number encoding".to_string());
254	        }
255	        if content.len() > 1 && content[0] == 0x00 && content[1] & 0x80 == 0 {
256	            return Err("non-minimal serial number encoding".to_string());
257	        }
258	        if content[0] & 0x80 != 0 && !(content.len() > 1 && content[0] == 0x00) {
259	            return Err("negative serial number".to_string());
260	        }
261	        let digits = if content.len() > 1 && content[0] == 0x00 {
262	            &content[1..]
263	        } else {
264	            content
265	        };
266	        let mut s = String::with_capacity(digits.len() * 2);
267	        for b in digits {
268	            write!(s, "{b:02X}").unwrap();
269	        }
270	        if s.is_empty() {
271	            s.push_str("00");
272	        }
273	        Ok(s)
274	    }
275	
276	    /// Name ::= SEQUENCE OF RDN; rendered per RFC 4514 (RDNs reversed,
277	    /// multi-valued RDNs joined with '+'). Values are emitted as real UTF-8
278	    /// text so non-ASCII content is preserved verbatim.
279	    fn format_name(name: Tlv) -> Result<String, String> {
280	        let mut rdn_buf = name.content;
281	        let mut rdns: Vec<String> = Vec::new();
282	        while !rdn_buf.is_empty() {
283	            let (set, rest) = read_tagged(rdn_buf, TAG_SET, "RelativeDistinguishedName")?;
284	            rdn_buf = rest;
285	
286	            let mut atv_buf = set.content;
287	            let mut parts = Vec::new();
288	            while !atv_buf.is_empty() {
289	                let (atv, rest) =
290	                    read_tagged(atv_buf, TAG_SEQUENCE, "AttributeTypeAndValue")?;
291	                atv_buf = rest;
292	
293	                let (oid, after_oid) = read_tagged(atv.content, TAG_OID, "attribute OID")?;
294	                let (value, after_value) = read_tlv(after_oid)?;
295	                if !after_value.is_empty() {
296	                    return Err("trailing data in attribute value".to_string());
297	                }
298	
299	                let oid_arcs = parse_oid(oid.content)?;
300	                let label = oid_short_name(&oid_arcs)
301	                    .map(str::to_string)
302	                    .unwrap_or_else(|| arcs_to_string(&oid_arcs));
303	                let text = decode_attribute_value(value.tag, value.content)?;
304	                parts.push(format!("{label}={}", escape_value(&text)));
305	            }
306	            if parts.is_empty() {
307	                return Err("empty RelativeDistinguishedName".to_string());
308	            }
309	            rdns.push(parts.join("+"));
310	        }
311	        rdns.reverse();
312	        Ok(rdns.join(","))
313	    }
314	
315	    fn parse_oid(content: &[u8]) -> Result<Vec<u64>, String> {
316	        if content.is_empty() {
317	            return Err("empty OID".to_string());
318	        }
319	        let mut arcs = Vec::new();
320	        let first = content[0];
321	        match first {
322	            0..=39 => {
323	                arcs.push(0);
324	                arcs.push(first as u64);
325	            }
326	            40..=79 => {
327	                arcs.push(1);
328	                arcs.push(first as u64 - 40);
329	            }
330	            _ => {
331	                arcs.push(2);
332	                arcs.push(first as u64 - 80);
333	            }
334	        }
335	        let mut i = 1;
336	        while i < content.len() {
337	            let mut value = 0u64;
338	            let start = i;
339	            loop {
340	                let b = content[i];
341	                value = value
342	                    .checked_mul(128)
343	                    .and_then(|v| v.checked_add((b & 0x7F) as u64))
344	                    .ok_or_else(|| "OID arc overflow".to_string())?;
345	                i += 1;
346	                if b & 0x80 == 0 {
347	                    break;
348	                }
349	                if i >= content.len() {
350	                    return Err("truncated OID arc".to_string());
351	                }
352	            }
353	            if i - start > 1 && content[start] == 0x80 {
354	                return Err("non-minimal OID arc encoding".to_string());
355	            }
356	            arcs.push(value);
357	        }
358	        Ok(arcs)
359	    }
360	
361	    fn arcs_to_string(arcs: &[u64]) -> String {
362	        arcs.iter()
363	            .map(u64::to_string)
364	            .collect::<Vec<_>>()
365	            .join(".")
366	    }
367	
368	    fn oid_short_name(arcs: &[u64]) -> Option<&'static str> {
369	        // X.520 / X.521 (2.5.4.*) and the commonly used LDAP/PKCS names.
370	        let name = match arcs {
371	            [2, 5, 4, 3] => "CN",
372	            [2, 5, 4, 4] => "SN",
373	            [2, 5, 4, 5] => "serialNumber",
374	            [2, 5, 4, 6] => "C",
375	            [2, 5, 4, 7] => "L",
376	            [2, 5, 4, 8] => "ST",
377	            [2, 5, 4, 9] => "STREET",
378	            [2, 5, 4, 10] => "O",
379	            [2, 5, 4, 11] => "OU",
380	            [2, 5, 4, 12] => "title",
381	            [2, 5, 4, 17] => "postalAddress",
382	            [2, 5, 4, 18] => "postalCode",
383	            [2, 5, 4, 20] => "telephoneNumber",
384	            [2, 5, 4, 42] => "givenName",
385	            [2, 5, 4, 43] => "initials",
386	            [2, 5, 4, 44] => "generationQualifier",
387	            [2, 5, 4, 46] => "dnQualifier",
388	            [2, 5, 4, 65] => "pseudonym",
389	            [0, 9, 2342, 19200300, 100, 1, 1] => "UID",
390	            [0, 9, 2342, 19200300, 100, 1, 25] => "DC",
391	            [1, 2, 840, 113549, 1, 9, 1] => "emailAddress",
392	            _ => return None,
393	        };
394	        Some(name)
395	    }
396	
397	    /// Decode a DirectoryString-style attribute value into UTF-8 text.
398	    fn decode_attribute_value(tag: u8, content: &[u8]) -> Result<String, String> {
399	        let s = match tag {
400	            0x0C => std::str::from_utf8(content)
401	                .map_err(|_| "invalid UTF-8 in UTF8String".to_string())?
402	                .to_string(),
403	            // ASCII-family strings: every byte is also its Unicode code point.
404	            0x12 | 0x13 | 0x16 | 0x1A => content.iter().map(|&b| b as char).collect(),
405	            // T.61 / GeneralString are conventionally treated as Latin-1 here.
406	            0x14 | 0x1B => content.iter().map(|&b| b as char).collect(),
407	            0x1E => {
408	                if content.len() % 2 != 0 {
409	                    return Err("odd-length BMPString".to_string());
410	                }
411	                let units: Vec<u16> = content
412	                    .chunks_exact(2)
413	                    .map(|c| u16::from_be_bytes([c[0], c[1]]))
414	                    .collect();
415	                char::decode_utf16(units.iter().copied())
416	                    .map(|r| r.map_err(|_| "unpaired surrogate in BMPString".to_string()))
417	                    .collect::<Result<String, _>>()?
418	            }
419	            0x1C => {
420	                if content.len() % 4 != 0 {
421	                    return Err("invalid UniversalString length".to_string());
422	                }
423	                let mut s = String::new();
424	                for c in content.chunks_exact(4) {
425	                    let cp = u32::from_be_bytes([c[0], c[1], c[2], c[3]]);
426	                    if (0xD800..=0xDFFF).contains(&cp) || cp > 0x10FFFF {
427	                        return Err("invalid code point in UniversalString".to_string());
428	                    }
429	                    s.push(char::from_u32(cp).unwrap());
430	                }
431	                s
432	            }
433	            _ => {
434	                return Err(format!(
435	                    "unsupported attribute value string type (tag 0x{tag:02X})"
436	                ))
437	            }
438	        };
439	        Ok(s)
440	    }
441	
442	    /// RFC 4514 value escaping; everything above the ASCII control range
443	    /// (including CJK text) passes through unchanged.
444	    fn escape_value(value: &str) -> String {
445	        let mut out = String::with_capacity(value.len());
446	        let last = value.chars().count().saturating_sub(1);
447	        for (i, c) in value.chars().enumerate() {
448	            let at_edge = i == 0 || i == last;
449	            let needs_backslash = matches!(c, ',' | '+' | '"' | '\\' | '<' | '>' | ';')
450	                || (at_edge && (c == ' ' || c == '#'));
451	            if needs_backslash {
452	                out.push('\\');
453	                out.push(c);
454	            } else if ('\0'..='\x1F').contains(&c) || c == '\x7F' {
455	                let mut buf = [0u8; 4];
456	                let b = c.encode_utf8(&mut buf).as_bytes()[0];
457	                write!(out, "\\{b:02X}").unwrap();
458	            } else {
459	                out.push(c);
460	            }
461	        }
462	        out
463	    }
464	
465	    fn format_time(tlv: Tlv) -> Result<String, String> {
466	        let (y, mo, d, h, mi, se) = match tlv.tag {
467	            TAG_UTC_TIME => {
468	                let c = tlv.content;
469	                if c.len() != 13 || c[12] != b'Z' {
470	                    return Err("UTCTime must be YYMMDDHHMMSSZ".to_string());
471	                }
472	                let digits = &c[..12];
473	                if !digits.iter().all(|b| b.is_ascii_digit()) {
474	                    return Err("non-numeric UTCTime".to_string());
475	                }
476	                let n = |a: usize, b: usize| -> u32 {
477	                    digits[a..=b].iter().fold(0, |acc, x| acc * 10 + (x - b'0') as u32)
478	                };
479	                let yy = n(0, 1);
480	                let year = if yy < 50 { 2000 + yy } else { 1900 + yy };
481	                (year as i32, n(2, 3), n(4, 5), n(6, 7), n(8, 9), n(10, 11))
482	            }
483	            TAG_GENERALIZED_TIME => {
484	                let c = tlv.content;
485	                if c.len() != 15 || c[14] != b'Z' {
486	                    return Err(
487	                        "GeneralizedTime must be YYYYMMDDHHMMSSZ in UTC".to_string()
488	                    );
489	                }
490	                let digits = &c[..14];
491	                if !digits.iter().all(|b| b.is_ascii_digit()) {
492	                    return Err("non-numeric GeneralizedTime".to_string());
493	                }
494	                let n = |a: usize, b: usize| -> u32 {
495	                    digits[a..=b].iter().fold(0, |acc, x| acc * 10 + (x - b'0') as u32)
496	                };
497	                (n(0, 3) as i32, n(4, 5), n(6, 7), n(8, 9), n(10, 11), n(12, 13))
498	            }
499	            other => return Err(format!("invalid time tag 0x{other:02X}")),
500	        };
501	        validate_datetime(y, mo, d, h, mi, se)?;
502	        Ok(format!("{y:04}-{mo:02}-{d:02}T{h:02}:{mi:02}:{se:02}Z"))
503	    }
504	
505	    fn validate_datetime(
506	        year: i32,
507	        month: u32,
508	        day: u32,
509	        hour: u32,
510	        minute: u32,
511	        second: u32,
512	    ) -> Result<(), String> {
513	        if !(1..=12).contains(&month) {
514	            return Err("invalid month in certificate time".to_string());
515	        }
516	        if hour > 23 || minute > 59 || second > 59 {
517	            return Err("invalid time of day in certificate time".to_string());
518	        }
519	        let leap = year % 4 == 0 && (year % 100 != 0 || year % 400 == 0);
520	        let days = [31, if leap { 29 } else { 28 }, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
521	        if day < 1 || day > days[(month - 1) as usize] {
522	            return Err("invalid day in certificate time".to_string());
523	        }
524	        Ok(())
525	    }
526	}
